//testbench
//
// RHX-sequence testbench for the RHD2164x2 emulator (intan_rec_adapter).
//
// The SPI master below replays what the Intan RHD Recording Controller sends
// once RHX has uploaded its command lists (vega docs/interfaces/lvds-tunnel.md
// §9.1b, from Intan RHX source 3c58677):
//   one sample period = 35 SPI words:
//     words 0-31 : CONVERT(0) ... CONVERT(31)  (generated by Rhythm)
//     word  32   : AuxCmd1[s]  WRITE(3, ...) every sample
//     word  33   : AuxCmd2[s]  CONVERT(32/33/34), READ(40), CONVERT(48)
//     word  34   : AuxCmd3[s]  register config + ROM reads (bank 0, with CALIBRATE)
//   where s is the sample period within the 128-period data block.
//   The slot order is inferred, not yet confirmed on the scope (§9.1b).
//
// Two independent checks:
//   1. Every command except CONVERT is answered exactly two words later, on
//      MISO A and B of both lines, with the datasheet response (§9.1, §9.3):
//        READ(R)      {8'h00, value}; register 59 reads 53 on A, 58 on B
//        WRITE(R,D)   {8'hFF, D}  -- echoes the host's D; the write is absorbed
//      The host's D values differ from Kuntur's on every register (host_val),
//      as RHX's do (e.g. register 4 twosComp = 0), so a later READ(0..21)
//      that returns the host's value instead of Kuntur's fails (§9.3).
//        CALIBRATE    RHD_CALIBRATE_RSPND_2C or _OTHER, following Kuntur's
//        CLEAR        RHD_TWOSCMP (the emulator answers as Kuntur's chips)
//      On a mismatch the tb reports whether the answer belongs to the word
//      one earlier or one later, i.e. a pipeline depth of 1 or 3 instead of 2.
//      CONVERT answers are not checked yet: there is no sample data (§9.2).
//      READ values come from the rhd2164_defs.vh macros, the same source as
//      the ROM, so this checks transport and pipeline, not the macros.
//   2. RHX's own detection, as in RHXDataBlock::getChipID(): AuxCmd3 results
//      read at sample indices 19 (chip ID), 23 (reg 59), 24-26 ("RHD") and
//      32-36 ("INTAN"), on MISO A of each line. Compared against literal
//      values, independent of the macros.
//
// Run long enough: N_SAMPLES x 35 words x 20 SCLK periods (~2.0 ms at the
// defaults); qrun.f uses "run -all" and the tb ends itself with $finish.


`timescale 1ns/1ps
`include "intan_rec_adapter.v"

module tb();

	// parameters
	localparam real T_SCK = 47.619;		// 21 MHz = 2800 x 30 kS/s / 4 (inferred, §9.1a)
	localparam real T_CLKIN = 83.333;	// 12 MHz on-board oscillator
	localparam integer WPS = 35;		// SPI words per sample period
	localparam integer N_SAMPLES = 60;	// AuxCmd3 entries 0-58: CALIBRATE is 54, WRITE(21) is 58
	localparam integer NW = N_SAMPLES*WPS;	// total SPI words

	// RHX-checked literals (rhxdatablock.cpp, getChipID)
	localparam [15:0] RHX_CHIPID_RHD2164 = 16'd4;
	localparam [15:0] RHX_REG59_MISOA = 16'd53;
	localparam [7:0]  REG59_MISOB = 8'd58;	// spec §9.1; not checked by RHX

	// DUT signals
	reg rstb, clkin;
	reg csb, sck, mosi;
	wire miso0, miso1, led_out;

	// command lists and logs
	reg [15:0] aux1 [0:127];
	reg [15:0] aux2 [0:127];
	reg [15:0] aux3 [0:127];
	reg [15:0] cmd_log [0:NW-1];
	reg [15:0] a0_log [0:NW-1];
	reg [15:0] b0_log [0:NW-1];
	reg [15:0] a1_log [0:NW-1];
	reg [15:0] b1_log [0:NW-1];

	// counters
	integer n_read, n_write, n_calclr, n_fail, n_unchecked;
	integer i, s, w, k;


	// DUT
	intan_rec_adapter dut (
		.rstb	(rstb),
		.clkin	(clkin),			// L13 (12 MHz)
		// SPI to Intan Recording Controller
		.spi0_csb	(csb),
		.spi0_sck	(sck),
		.spi0_mosi	(mosi),
		.spi0_miso1	(miso1),
		.spi0_miso0	(miso0),
		// LED visualizer
		.led_out	(led_out)
	);

	always #(T_CLKIN/2) clkin = ~clkin;


	// RHD commands (RHXRegisters::createRHXCommand)
	function [15:0] cmd_convert(input [5:0] c);
		cmd_convert = {2'b00, c, 8'h00};
	endfunction

	function [15:0] cmd_read(input [5:0] r);
		cmd_read = {2'b11, r, 8'h00};
	endfunction

	function [15:0] cmd_write(input [5:0] r, input [7:0] d);
		cmd_write = {2'b10, r, d};
	endfunction

	localparam [15:0] CMD_CALIBRATE = `RHD_CALIBRATE;	// 16'h5500
	localparam [15:0] CMD_CLEAR = `RHD_CLEAR;		// 16'h6A00

	// Datasheet responses that depend on register 4's twoscomp bit
	localparam [15:0] RSPND_CALIBRATE = `RHD_TWOSCMP ? `RHD_CALIBRATE_RSPND_2C : `RHD_CALIBRATE_RSPND_OTHER;
	localparam [15:0] RSPND_CLEAR = `RHD_TWOSCMP ? `RHD_CLEAR_RSPND_2C : `RHD_CLEAR_RSPND_OTHER;


	// Expected register value, from the same macros as the ROM
	function [7:0] reg_val(input [5:0] r);
		case (r)
			6'd0: reg_val = `RHD_REG0;
			6'd1: reg_val = `RHD_REG1;
			6'd2: reg_val = `RHD_REG2;
			6'd3: reg_val = `RHD_REG3;
			6'd4: reg_val = `RHD_REG4;
			6'd5: reg_val = `RHD_REG5;
			6'd6: reg_val = `RHD_REG6;
			6'd7: reg_val = `RHD_REG7;
			6'd8: reg_val = `RHD_REG8;
			6'd9: reg_val = `RHD_REG9;
			6'd10: reg_val = `RHD_REG10;
			6'd11: reg_val = `RHD_REG11;
			6'd12: reg_val = `RHD_REG12;
			6'd13: reg_val = `RHD_REG13;
			6'd14: reg_val = `RHD_REG14;
			6'd15: reg_val = `RHD_REG15;
			6'd16: reg_val = `RHD_REG16;
			6'd17: reg_val = `RHD_REG17;
			6'd18: reg_val = `RHD_REG18;
			6'd19: reg_val = `RHD_REG19;
			6'd20: reg_val = `RHD_REG20;
			6'd21: reg_val = `RHD_REG21;
			6'd40: reg_val = `RHD_REG40_VAL;
			6'd41: reg_val = `RHD_REG41_VAL;
			6'd42: reg_val = `RHD_REG42_VAL;
			6'd43: reg_val = `RHD_REG43_VAL;
			6'd44: reg_val = `RHD_REG44_VAL;
			6'd45: reg_val = `RHD_REG45_VAL;
			6'd46: reg_val = `RHD_REG46_VAL;
			6'd47: reg_val = `RHD_REG47_VAL;
			6'd48: reg_val = `RHD_REG48_VAL;
			6'd49: reg_val = `RHD_REG49_VAL;
			6'd50: reg_val = `RHD_REG50_VAL;
			6'd51: reg_val = `RHD_REG51_VAL;
			6'd52: reg_val = `RHD_REG52_VAL;
			6'd53: reg_val = `RHD_REG53_VAL;
			6'd54: reg_val = `RHD_REG54_VAL;
			6'd55: reg_val = `RHD_REG55_VAL;
			6'd56: reg_val = `RHD_REG56_VAL;
			6'd57: reg_val = `RHD_REG57_VAL;
			6'd58: reg_val = `RHD_REG58_VAL;
			6'd59: reg_val = `RHD_REG59_VAL;
			6'd60: reg_val = `RHD_REG60_VAL;
			6'd61: reg_val = `RHD_REG61_VAL;
			6'd62: reg_val = `RHD_REG62_VAL;
			6'd63: reg_val = `RHD_REG63_VAL;
			default: reg_val = 8'h00;	// 22-39: no register
		endcase
	endfunction


	// What the host writes: deliberately different from Kuntur's value on
	// every register, so an applied write is visible on the next READ.
	function [7:0] host_val(input [5:0] r);
		host_val = reg_val(r) ^ 8'h5A;
	endfunction


	// Build the three aux lists exactly as RHX does for 128 commands
	// (rhxregisters.cpp: createCommandListRHDUpdateDigOut, ...SampleAuxIns,
	//  ...RegisterConfig with calibrate = true)
	task build_aux_lists;
		integer n;
		begin
			// AuxCmd1: WRITE(3) every sample period
			for (n = 0; n < 128; n = n + 1)
				aux1[n] = cmd_write(6'd3, host_val(6'd3));

			// AuxCmd2: AuxIn1-3 + READ(40), with one CONVERT(48) near the end
			n = 0;
			for (i = 0; i < (128/4) - 2; i = i + 1) begin
				aux2[n] = cmd_convert(6'd32); n = n + 1;
				aux2[n] = cmd_convert(6'd33); n = n + 1;
				aux2[n] = cmd_convert(6'd34); n = n + 1;
				aux2[n] = cmd_read(6'd40);    n = n + 1;
			end
			aux2[n] = cmd_convert(6'd32); n = n + 1;
			aux2[n] = cmd_convert(6'd33); n = n + 1;
			aux2[n] = cmd_convert(6'd34); n = n + 1;
			aux2[n] = cmd_convert(6'd48); n = n + 1;
			aux2[n] = cmd_convert(6'd32); n = n + 1;
			aux2[n] = cmd_convert(6'd33); n = n + 1;
			aux2[n] = cmd_convert(6'd34); n = n + 1;
			aux2[n] = cmd_read(6'd40);    n = n + 1;

			// AuxCmd3, bank 0
			n = 0;
			aux3[n] = cmd_read(6'd63); n = n + 1;	// dummies
			aux3[n] = cmd_read(6'd63); n = n + 1;
			aux3[n] = cmd_write(6'd0, host_val(6'd0)); n = n + 1;	// RAM, skips 3 and 6
			aux3[n] = cmd_write(6'd1, host_val(6'd1)); n = n + 1;
			aux3[n] = cmd_write(6'd2, host_val(6'd2)); n = n + 1;
			aux3[n] = cmd_write(6'd4, host_val(6'd4)); n = n + 1;
			aux3[n] = cmd_write(6'd5, host_val(6'd5)); n = n + 1;
			for (i = 7; i <= 17; i = i + 1) begin
				aux3[n] = cmd_write(i[5:0], host_val(i[5:0])); n = n + 1;
			end
			aux3[n] = cmd_read(6'd63); n = n + 1;	// ROM: entry 18
			aux3[n] = cmd_read(6'd62); n = n + 1;
			aux3[n] = cmd_read(6'd61); n = n + 1;
			aux3[n] = cmd_read(6'd60); n = n + 1;
			aux3[n] = cmd_read(6'd59); n = n + 1;	// entry 22
			for (i = 48; i <= 55; i = i + 1) begin	// chip name: entries 23-30
				aux3[n] = cmd_read(i[5:0]); n = n + 1;
			end
			for (i = 40; i <= 44; i = i + 1) begin	// "INTAN": entries 31-35
				aux3[n] = cmd_read(i[5:0]); n = n + 1;
			end
			for (i = 0; i < 18; i = i + 1) begin	// RAM readback
				aux3[n] = cmd_read(i[5:0]); n = n + 1;
			end
			aux3[n] = CMD_CALIBRATE; n = n + 1;	// bank 0 only
			for (i = 18; i <= 21; i = i + 1) begin	// RHD2164 MISO B power regs
				aux3[n] = cmd_write(i[5:0], host_val(i[5:0])); n = n + 1;
			end
			aux3[n] = cmd_read(6'd63); n = n + 1;	// dummy
			if (n != 60) begin
				$display("TB ERROR: AuxCmd3 list has %0d commands, expected 60", n);
				$finish;
			end
			for (; n < 128; n = n + 1)
				aux3[n] = cmd_read(6'd63);
		end
	endtask


	// SPI master, one word. 20 SCLK periods per word: CS low, half a period,
	// 16 SCLK pulses, CS high for 3.5 periods. MOSI changes after each falling
	// edge (the chip samples it on the rising edge). MISO A is read a quarter
	// period after each rising edge, MISO B a quarter period after each
	// falling edge -- the DDR convention of spi_master_rhd2164x2.
	task spi_word(input [15:0] cmd,
				  output [15:0] a0, output [15:0] b0,
				  output [15:0] a1, output [15:0] b1);
		integer b;
		begin
			csb = 1'b0;
			mosi = cmd[15];
			#(T_SCK/2);
			for (b = 15; b >= 0; b = b - 1) begin
				sck = 1'b1;
				#(T_SCK/4);
				a0[b] = miso0;
				a1[b] = miso1;
				#(T_SCK/4);
				sck = 1'b0;
				if (b > 0)
					mosi = cmd[b-1];
				#(T_SCK/4);
				b0[b] = miso0;
				b1[b] = miso1;
				#(T_SCK/4);
			end
			csb = 1'b1;
			#(T_SCK*3.5);
		end
	endtask


	// Expected answer to command c on MISO A (b_side = 0) or B (b_side = 1):
	// {checked, value}. checked = 0 for CONVERT (no sample data yet).
	function [16:0] expect_ans(input [15:0] c, input b_side);
		if (c[15:14] == 2'b11)
			expect_ans = {1'b1, 8'h00,
				(b_side && c[13:8] == 6'd59) ? REG59_MISOB : reg_val(c[13:8])};
		else if (c[15:14] == 2'b10)
			expect_ans = {1'b1, 8'hFF, c[7:0]};
		else if (c == CMD_CALIBRATE)
			expect_ans = {1'b1, RSPND_CALIBRATE};
		else if (c == CMD_CLEAR)
			expect_ans = {1'b1, RSPND_CLEAR};
		else
			expect_ans = 17'd0;
	endfunction

	function [8*9-1:0] cmd_name(input [15:0] c);
		if (c[15:14] == 2'b11)       cmd_name = "READ";
		else if (c[15:14] == 2'b10)  cmd_name = "WRITE";
		else if (c == CMD_CALIBRATE) cmd_name = "CALIBRATE";
		else if (c == CMD_CLEAR)     cmd_name = "CLEAR";
		else if (c[15:14] == 2'b00)  cmd_name = "CONVERT";
		else                         cmd_name = "?";
	endfunction

	// Check 1: answer to word w-2 arrives in word w
	task check_word(input integer w);
		reg [15:0] c;
		reg [16:0] ea, eb, e1, e3;
		begin
			c = cmd_log[w-2];
			ea = expect_ans(c, 1'b0);
			eb = expect_ans(c, 1'b1);
			if (!ea[16])
				n_unchecked = n_unchecked + 1;
			else begin
				if (c[15:14] == 2'b11)      n_read = n_read + 1;
				else if (c[15:14] == 2'b10) n_write = n_write + 1;
				else                        n_calclr = n_calclr + 1;
				if (a0_log[w] !== ea[15:0] || a1_log[w] !== ea[15:0] ||
					b0_log[w] !== eb[15:0] || b1_log[w] !== eb[15:0]) begin
					n_fail = n_fail + 1;
					$display("FAIL word %0d (sample %0d, slot %0d): %0s %h sent in word %0d, expected A=%h B=%h, got A0=%h B0=%h A1=%h B1=%h",
						w, w/WPS, w%WPS, cmd_name(c), c, w-2, ea[15:0], eb[15:0],
						a0_log[w], b0_log[w], a1_log[w], b1_log[w]);
					// Depth diagnostic on READ failures only: the ROM-only RTL
					// answers other commands with the last READ value, which
					// would match a neighbouring READ by coincidence.
					e1 = expect_ans(cmd_log[w-1], 1'b0);
					if (c[15:14] == 2'b11 && e1[16] && a0_log[w] === e1[15:0] && e1[15:0] !== ea[15:0])
						$display("     -> A0 matches the %0s in word %0d: pipeline depth 1", cmd_name(cmd_log[w-1]), w-1);
					if (w >= 3) begin
						e3 = expect_ans(cmd_log[w-3], 1'b0);
						if (c[15:14] == 2'b11 && e3[16] && a0_log[w] === e3[15:0] && e3[15:0] !== ea[15:0])
							$display("     -> A0 matches the %0s in word %0d: pipeline depth 3", cmd_name(cmd_log[w-3]), w-3);
					end
				end
			end
		end
	endtask


	// Check 2: RHX getChipID() on the AuxCmd3 results. The aux3 command of
	// sample t is word 34; its answer is word 1 of sample t+1, which RHX files
	// at sample index t+1.
	function [15:0] aux3_result(input integer t, input integer line);
		aux3_result = (line == 0) ? a0_log[t*WPS + 1] : a1_log[t*WPS + 1];
	endfunction

	task check_rhx_detection(input integer line);
		reg intan_ok;
		begin
			intan_ok = (aux3_result(32, line) & 16'h00ff) == "I" &&
					   (aux3_result(33, line) & 16'h00ff) == "N" &&
					   (aux3_result(34, line) & 16'h00ff) == "T" &&
					   (aux3_result(35, line) & 16'h00ff) == "A" &&
					   (aux3_result(36, line) & 16'h00ff) == "N" &&
					   (aux3_result(24, line) & 16'h00ff) == "R" &&
					   (aux3_result(25, line) & 16'h00ff) == "H" &&
					   (aux3_result(26, line) & 16'h00ff) == "D";
			if (intan_ok && aux3_result(19, line) == RHX_CHIPID_RHD2164 &&
				aux3_result(23, line) == RHX_REG59_MISOA)
				$display("RHX detection, MISO%0d: PASS (RHD2164, chip ID %0d, reg 59 = %0d)",
					line + 1, aux3_result(19, line), aux3_result(23, line));
			else begin
				n_fail = n_fail + 1;
				$display("RHX detection, MISO%0d: FAIL  INTAN/RHD %s, chip ID %0d (want 4), reg 59 %0d (want 53)",
					line + 1, intan_ok ? "ok" : "BAD", aux3_result(19, line), aux3_result(23, line));
			end
		end
	endtask


	initial begin
		rstb = 1'b0;
		clkin = 1'b0;
		csb = 1'b1;
		sck = 1'b0;
		mosi = 1'b0;
		n_read = 0;
		n_write = 0;
		n_calclr = 0;
		n_fail = 0;
		n_unchecked = 0;

		build_aux_lists;

		#100; rstb = 1'b1;
		#(T_SCK*4);

		// replay N_SAMPLES sample periods
		w = 0;
		for (s = 0; s < N_SAMPLES; s = s + 1) begin
			for (k = 0; k < WPS; k = k + 1) begin
				if (k < 32)
					cmd_log[w] = cmd_convert(k[5:0]);
				else if (k == 32)
					cmd_log[w] = aux1[s % 128];
				else if (k == 33)
					cmd_log[w] = aux2[s % 128];
				else
					cmd_log[w] = aux3[s % 128];
				spi_word(cmd_log[w], a0_log[w], b0_log[w], a1_log[w], b1_log[w]);
				w = w + 1;
			end
		end

		// check 1
		for (w = 2; w < NW; w = w + 1)
			check_word(w);
		$display("Answer check: %0d READ, %0d WRITE, %0d CALIBRATE/CLEAR answers checked; %0d CONVERT answers not checked",
			n_read, n_write, n_calclr, n_unchecked);
		if (n_calclr == 0) begin
			n_fail = n_fail + 1;
			$display("TB ERROR: no CALIBRATE was sent -- N_SAMPLES too small");
		end

		// check 2
		check_rhx_detection(0);
		check_rhx_detection(1);

		if (n_fail == 0)
			$display("TB RESULT: PASS");
		else
			$display("TB RESULT: FAIL (%0d errors)", n_fail);
		$finish;
	end


endmodule
